/bin/bash -lc "node - <<'NODE'
const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const replies = [];
const state = new Map();
const list = {
  data(key, value) { if (arguments.length === 2) state.set(key, value); return state.get(key); },
  html(value) { this.rendered = value; return this; },
  off() { return this; },
  on() { return this; },
};
const noopChain = { off() { return this; }, on() { return this; } };
let notifications;
const context = {
  define(name, deps, factory) {
    notifications = factory({ toggleTimeagoShorthand() {} }, {}, {}, {},
      { on() {}, fire: async ({ notifications }) => ({ notifications }) }, {});
  },
  socket: { emit(name, data, callback) { replies.push(callback); } },
  app: { parseAndTranslate(name, data, callback) { callback(data.notifications[0].nid); } },
};
vm.runInNewContext(fs.readFileSync('public/src/modules/notifications.js', 'utf8'), context);
(async () => {
  notifications.loadNotifications(list, noopChain);
  notifications.loadNotifications(list, noopChain);
  replies[1](null, { unread: [{ nid: 'latest', datetime: '2' }], read: [] });
  await new Promise(resolve => setImmediate(resolve));
  replies[0](null, { unread: [{ nid: 'stale', datetime: '1' }], read: [] });
  await new Promise(resolve => setImmediate(resolve));
  assert.equal(list.rendered, 'latest');
  console.log('Notification refresh race check passed');
})().catch(err => { console.error(err); process.exitCode = 1; });
NODE"

